def orderedTreeRegion (h d : ℝ)
    (parent : (m : ℕ) → (Fin (m + 1) → Covariate) → Covariate) :
    (m : ℕ) → Set (Fin (m + 1) → Covariate)
  | 0 => {x | |(x 0 : ℝ) - x0| < h}
